// ============================================
// FIND TARGET ROW AND BUILD HISTORY
// ============================================

// Get day_index from chat message (just the number)
const chatData = $('Receive Day Number').first().json;
const messageText = chatData.chatInput || chatData.message || chatData.text || '';

// Extract the number from the message
const numberMatch = messageText.match(/\d+/);
const TARGET_DAY_INDEX = numberMatch ? parseInt(numberMatch[0]) : 8;

const allRows = $input.all().map(item => item.json);

// Find the target row
const targetRow = allRows.find(row => 
  String(row.day_index) === String(TARGET_DAY_INDEX)
);

if (!targetRow) {
  throw new Error(`No row found with day_index = ${TARGET_DAY_INDEX}. Please send a valid day number.`);
}

// Get artist name from the row
const artistName = targetRow.artist_name || 'Unknown Artist';
const galleryTotal = targetRow.gallery_total || '111';

// Check if already completed
if (targetRow.exhibition_title && targetRow.exhibition_title.trim() !== '') {
  throw new Error(`Day ${TARGET_DAY_INDEX} (${artistName}) already has content. Choose a different day or clear that row first.`);
}

// Get all completed rows (for history/deduplication)
const completedRows = allRows.filter(row => 
  row.exhibition_title && row.exhibition_title.trim() !== ''
);

// Build deduplication lists
const usedPractices = completedRows
  .map(r => (r.practice || '').substring(0, 100))
  .filter(p => p)
  .join('\n- ');

const usedMusic = completedRows
  .map(r => {
    const music = r.cultural_music || '';
    const match = music.match(/^([^(]+)/);
    return match ? match[1].trim() : '';
  })
  .filter(m => m)
  .join('\n- ');

const usedPoems = completedRows
  .map(r => `${r.poem_author || ''} - ${r.poem_work || ''}`)
  .filter(p => p !== ' - ')
  .join('\n- ');

return {
  targetRow: targetRow,
  dayIndex: TARGET_DAY_INDEX,
  galleryTotal: galleryTotal,
  artistName: artistName,
  usedPractices: usedPractices,
  usedMusic: usedMusic,
  usedPoems: usedPoems,
  completedCount: completedRows.length
};

// ============================================
// PARSE AI RESPONSE
// ============================================

const prevData = $('Build AI Prompt').first().json;
const rawResponse = $input.first().json.message?.content || $input.first().json.text || $input.first().json.content || '';

// Handle array response from Claude
let response = rawResponse;
if (Array.isArray(rawResponse)) {
  response = rawResponse.map(item => item.text || '').join('');
}
if (typeof response === 'object' && response !== null) {
  response = JSON.stringify(response);
}

// Split into lines and find the data row
const lines = response.trim().split('\n').filter(l => l.trim() && l.includes('|'));

let dataRow = '';
if (lines.length >= 2) {
  dataRow = lines[1];
} else if (lines.length === 1) {
  dataRow = lines[0];
}

if (!dataRow) {
  throw new Error('Could not parse AI response. No pipe-delimited data found.');
}

// Parse the pipe-delimited row
const columns = [
  'day_index', 'gallery_total', 'exhibition_title', 'artist_name', 'artist_portrait_url',
  'brand_name', 'hero_url', 'hero_title', 'hero_year', 'hero_alt', 'hook_text',
  'art2_url', 'art2_title', 'art2_year', 'art2_alt', 'why_it_matters',
  'notice_bullet_1', 'notice_bullet_2', 'notice_bullet_3', 'notice_bullet_4', 'notice_bullet_5',
  'practice', 'style_art_url', 'style_art_title', 'style_art_year', 'style_art_alt',
  'sticky_story', 'cultural_music', 'philosophy',
  'mini1_url', 'mini1_title', 'mini1_year', 'mini1_alt',
  'mini2_url', 'mini2_title', 'mini2_year', 'mini2_alt',
  'poem_line_1', 'poem_line_2', 'poem_author', 'poem_work', 'poem_source_url',
  'sticky_story_source_url'
];

const values = dataRow.split('|');
const parsed = {};

columns.forEach((col, idx) => {
  parsed[col] = (values[idx] || '').trim();
});

// Override day_index with actual value
parsed.day_index = String(prevData.dayIndex);

return {
  parsed: parsed,
  dayIndex: prevData.dayIndex,
  artistName: prevData.artistName
};

// Return success message to chat
const data = $('Parse AI Response').first().json;
return {
  response: `✅ Edition generated for Day ${data.dayIndex}: ${data.artistName}\n\nExhibition: ${data.parsed.exhibition_title}\n\nThe content has been saved to your Google Sheet.`
};
